import numpy as np
from scipy.optimize import minimize
def cols_for(Gv):
    cols=[]
    for j in range(4):
        cols += [P**j, P**j*Gv, P**j*t]
    return cols
def sc(th):
    k,t0=th
    Gv=1/(1+np.exp(-k*(t-t0)))
    X=np.array(cols_for(Gv)).T
    b=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((X@b-dP_dt)**2)/np.var(dP_dt)
best=None
for k0 in [0.2,0.5,1.0]:
    for t00 in [-2,0,2,5]:
        r=minimize(sc,[k0,t00],method='Nelder-Mead',options={'xatol':1e-10,'fatol':1e-14,'maxiter':3000})
        if best is None or r.fun<best.fun: best=r
print(best.x,best.fun)

import numpy as np
from scipy.optimize import minimize
def sc_arg(th, form):
    k,c=th
    if form=='kt(1+cP)': a=k*t*(1+c*P)
    elif form=='kt+cP': a=k*t+c*P
    elif form=='kt*exp(cP)': a=k*t*np.exp(c*P)
    Gv=np.tanh(a)
    cols=[]
    for j in range(4):
        for v in [1,Gv,t,t*Gv]:
            cols.append(P**j*v)
    X=np.array(cols).T
    b=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((X@b-dP_dt)**2)/np.var(dP_dt)
for form in ['kt(1+cP)','kt+cP','kt*exp(cP)']:
    best=None
    for c0 in [-0.3,0.0,0.3]:
        r=minimize(sc_arg,[0.23,c0],args=(form,),method='Nelder-Mead',options={'xatol':1e-10,'fatol':1e-15,'maxiter':2000})
        if best is None or r.fun<best.fun: best=r
    print(form,best.x,best.fun)
